## WebMCP tools
name="get_analysis_context", description="現在の店舗・期間・指標・集計軸、画面版、データ版と参照可能範囲を取得します。分析前および人が条件を変えた後に使います。", inputSchema={"type":"object","properties":{},"required":[],"additionalProperties":false}, annotations={"readOnly":true,"untrustedContent":false,"consequential":false}
name="compare_periods", description="2期間の値・差分・増減率を店舗別、カテゴリ別または商品別に比較します。省略した条件は context_id の画面条件を引き継ぎます。画面は変更しません。表示は present_result で行います。", inputSchema={"type":"object","properties":{"context_id":{"type":"string","minLength":1,"maxLength":128},"base_period":{"type":"object","properties":{"start":{"type":"string","minLength":1,"maxLength":10},"end":{"type":"string","minLength":1,"maxLength":10}},"required":["start","end"],"additionalProperties":false},"target_period":{"type":"object","properties":{"start":{"type":"string","minLength":1,"maxLength":10},"end":{"type":"string","minLength":1,"maxLength":10}},"required":["start","end"],"additionalProperties":false},"metric":{"type":"string","enum":["net_sales","gross_profit","units","gross_margin","avg_unit_price"]},"group_by":{"type":"string","enum":["store","category","product"]},"filters":{"type":"object","properties":{"store_ids":{"type":"array","items":{"type":"string","minLength":1,"maxLength":128},"minItems":1,"maxItems":10,"description":"1件以上。現在条件は get_analysis_context から取得。"},"category_ids":{"type":"array","items":{"type":"string","minLength":1,"maxLength":128},"minItems":0,"maxItems":20,"description":"空配列は選択店舗の全カテゴリ。"},"product_ids":{"type":"array","items":{"type":"string","minLength":1,"maxLength":128},"minItems":0,"maxItems":20,"description":"空配列は選択カテゴリの全商品。"}},"required":["store_ids"],"additionalProperties":false},"limit":{"type":"integer","minimum":1,"maximum":100}},"required":["context_id"],"additionalProperties":false}, annotations={"readOnly":true,"untrustedContent":false,"consequential":false}
name="query_metrics", description="指定期間の売上、粗利、数量または比率を集計します。省略した条件は context_id の画面条件を使います。比率は分子・分母を再集計します。画面は変更しません。", inputSchema={"type":"object","properties":{"context_id":{"type":"string","minLength":1,"maxLength":128},"base_period":{"type":"object","properties":{"start":{"type":"string","minLength":1,"maxLength":10},"end":{"type":"string","minLength":1,"maxLength":10}},"required":["start","end"],"additionalProperties":false},"target_period":{"type":"object","properties":{"start":{"type":"string","minLength":1,"maxLength":10},"end":{"type":"string","minLength":1,"maxLength":10}},"required":["start","end"],"additionalProperties":false},"metric":{"type":"string","enum":["net_sales","gross_profit","units","gross_margin","avg_unit_price"]},"group_by":{"type":"string","enum":["store","category","product"]},"filters":{"type":"object","properties":{"store_ids":{"type":"array","items":{"type":"string","minLength":1,"maxLength":128},"minItems":1,"maxItems":10,"description":"1件以上。現在条件は get_analysis_context から取得。"},"category_ids":{"type":"array","items":{"type":"string","minLength":1,"maxLength":128},"minItems":0,"maxItems":20,"description":"空配列は選択店舗の全カテゴリ。"},"product_ids":{"type":"array","items":{"type":"string","minLength":1,"maxLength":128},"minItems":0,"maxItems":20,"description":"空配列は選択カテゴリの全商品。"}},"required":["store_ids"],"additionalProperties":false},"limit":{"type":"integer","minimum":1,"maximum":100}},"required":["context_id"],"additionalProperties":false}, annotations={"readOnly":true,"untrustedContent":false,"consequential":false}
name="present_result", description="取得済みの結果を条件・表・グラフと一緒に表示します。可逆な画面変更です。画面が変わった場合は古い結果を拒否します。VIEW_CHANGED の後は条件取得・再集計が必要です。", inputSchema={"type":"object","properties":{"result_id":{"type":"string","minLength":1,"maxLength":128},"expected_view_version":{"type":"integer","minimum":1},"view_type":{"type":"string","enum":["table","bar"]}},"required":["result_id","expected_view_version","view_type"],"additionalProperties":false}, annotations={"readOnly":false,"untrustedContent":false,"consequential":false}
name="create_report_draft", description="集計結果を根拠として、新しい未保存のレポート下書きをページ内に作ります。既存の下書きは編集しません。保存・共有・送信は行いません。同じキー・同じ内容の再実行は重複しません。", inputSchema={"type":"object","properties":{"result_ids":{"type":"array","items":{"type":"string","minLength":1,"maxLength":128},"minItems":1,"maxItems":5},"title":{"type":"string","minLength":1,"maxLength":100},"notes":{"type":"string","maxLength":2000},"idempotency_key":{"type":"string","minLength":1,"maxLength":128}},"required":["result_ids","title","notes","idempotency_key"],"additionalProperties":false}, annotations={"readOnly":false,"untrustedContent":true,"consequential":false}
